package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.result;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.get;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;

final class DemandPlanningAcceptance {
 static String api(String id){return "/api/openservice/demands/"+id+"/planning";}
 static String record(String id){return "/api/now/table/demand/"+id;}
 static String board(String id){return "/api/openservice/portfolios/"+id+"/demands?year=2027";}
 static String reviews(String id){return "/api/openservice/records/demand/"+id+"/approvals";}
 static String create(WorkflowSupport h,String label)throws Exception{return result(h.json("POST","/api/now/table/demand",map("short_description",label,"description","Retained business case"),auth("DemandPlanner"))).get("sys_id").toString();}
 static String[] setup(WorkflowSupport h)throws Exception{for(String user:List.of("DemandPlanner","DemandReviewer","DemandOther"))h.account(user,"agent");h.account("DemandReader","reader");String portfolio=result(h.json("POST","/api/now/table/portfolio",map("short_description","Customer experience investment"),auth("DemandPlanner"))).get("sys_id").toString();return new String[]{create(h,"Demand <script>"),portfolio};}
 static Map<String,Object> body(WorkflowSupport h,String id,String portfolio)throws Exception{var p=get(h,api(id),"DemandPlanner");return map("operation","assess","revision",p.get("revision"),"record_revision",Integer.parseInt(object(p.get("record")).get("sys_mod_count").toString()),"portfolio_id",portfolio,"year",2027,"value",5,"alignment",4,"urgency",3,"effort",2,"rationale","Prioritize service improvement <script>");}
 static Map<String,Object> save(WorkflowSupport h,String id,Map<String,Object> body)throws Exception{return result(h.json("POST",api(id),body,auth("DemandPlanner")));}
 static void state(WorkflowSupport h,String id,String state,int expected)throws Exception{var response=h.json("PATCH",record(id),map("state",state),auth("DemandPlanner"));assertEquals(expected,response.statusCode(),html(response));}
 static Map<String,Object> decision(WorkflowSupport h,String id,String outcome)throws Exception{var p=get(h,api(id),"DemandPlanner");return map("operation","decide","revision",p.get("revision"),"record_revision",Integer.parseInt(object(p.get("record")).get("sys_mod_count").toString()),"decision",outcome,"rationale","Retained investment decision");}
 static String approve(WorkflowSupport h,String id)throws Exception{String approval=result(h.json("POST",reviews(id),map("expected_revision",Integer.parseInt(get(h,record(id),"DemandPlanner").get("sys_mod_count").toString()),"approver","DemandReviewer","target_state","approved","reason","Review the qualified demand and its assessment"),auth("DemandPlanner"))).get("approval_id").toString();result(h.json("POST",reviews(id)+"/"+approval+"/decision",map("decision","approved","comment","Current business case and scoring reviewed"),auth("DemandReviewer")));return approval;}
 static void qualify(WorkflowSupport h,String id)throws Exception{state(h,id,"screen",200);state(h,id,"qualified",200);}
 static void run(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];assertEquals(200,h.get("/api/openservice/portfolios",auth("DemandPlanner")).statusCode());assertEquals(false,get(h,api(id),"DemandPlanner").get("current"));assertTrue(objects(get(h,board(ids[1]),"DemandPlanner").get("items")).isEmpty());state(h,id,"screen",200);state(h,id,"qualified",409);var p=save(h,id,body(h,id,ids[1]));assertEquals(84,object(p.get("assessment")).get("score"));assertEquals(true,p.get("current"));state(h,id,"qualified",200);assertEquals(409,h.json("POST",api(id),decision(h,id,"approved"),auth("DemandPlanner")).statusCode());assertEquals(1,get(h,api(id),"DemandPlanner").get("revision"));approve(h,id);state(h,id,"approved",409);var decided=save(h,id,decision(h,id,"approved"));assertEquals("approved",object(decided.get("record")).get("state"));assertEquals(2,objects(decided.get("history")).size());result(h.json("PATCH",record(id),map(),auth("DemandPlanner")));assertEquals(409,h.json("PATCH",record(id),map("description","Unreviewed replacement"),auth("DemandPlanner")).statusCode());assertEquals(409,h.json("POST",api(id),body(h,id,ids[1]),auth("DemandPlanner")).statusCode());state(h,id,"screen",200);state(h,id,"qualified",409);var next=body(h,id,ids[1]);next.putAll(map("value",1,"alignment",1,"urgency",1,"effort",5));assertEquals(20,object(save(h,id,next).get("assessment")).get("score"));state(h,id,"qualified",200);save(h,id,decision(h,id,"deferred"));assertEquals(0,objects(get(h,board(ids[1]),"DemandPlanner").get("items")).getFirst().get("rank"));state(h,id,"screen",200);save(h,id,body(h,id,ids[1]));state(h,id,"qualified",200);save(h,id,decision(h,id,"rejected"));new Store(h.environment);assertEquals(6,objects(get(h,api(id),"DemandReviewer").get("history")).size());assertEquals(204,h.json("DELETE",record(id),map(),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_demand_assessment WHERE record_id=?",id));}
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];assertEquals(401,h.get(api(id),null).statusCode());assertEquals(403,h.get(api(id),auth("DemandReader")).statusCode());assertEquals(405,h.json("PUT",api(id),map(),auth("DemandPlanner")).statusCode());assertEquals(400,h.get(api(id)+"?q=x",auth("DemandPlanner")).statusCode());assertEquals(400,h.get(board(ids[1])+"&unknown=x",auth("DemandPlanner")).statusCode());for(var change:List.of(map("operation","other"),map("extra",1),map("year",1999),map("year",2201),map("year","2027"),map("value",0),map("alignment",6),map("urgency","2"),map("effort",2.5),map("rationale",""),map("revision",-1))){var bad=body(h,id,ids[1]);bad.putAll(change);assertEquals(400,h.json("POST",api(id),bad,auth("DemandPlanner")).statusCode());}for(String key:List.of("revision","record_revision")){var bad=body(h,id,ids[1]);bad.put(key,999);assertEquals(409,h.json("POST",api(id),bad,auth("DemandPlanner")).statusCode());}assertEquals(404,h.json("POST",api(id),body(h,id,Values.id()),auth("DemandPlanner")).statusCode());assertEquals(409,h.json("POST",api(id),decision(h,id,"approved"),auth("DemandPlanner")).statusCode());save(h,id,body(h,id,ids[1]));qualify(h,id);assertEquals(400,h.json("POST",api(id),decision(h,id,"other"),auth("DemandPlanner")).statusCode());assertEquals(400,h.protectedForm("/record/demand/"+id+"/planning",map("operation","assess","revision","bad"),auth("DemandPlanner")).statusCode());for(String state:List.of("screen","qualified","approved","deferred","rejected"))assertEquals(409,h.json("POST","/api/openservice/import/demand?dry_run=false",List.of(map("sys_id",Values.id(),"short_description","Forged demand","state",state)),auth("admin")).statusCode());
 }
 static void ranking(WorkflowSupport h)throws Exception{
  var ids=setup(h);String first=ids[0],second=create(h,"Another demand"),third=create(h,"Hidden demand");save(h,first,body(h,first,ids[1]));save(h,second,body(h,second,ids[1]));var high=body(h,third,ids[1]);high.putAll(map("value",5,"alignment",5,"urgency",5,"effort",1));assertEquals(100,object(save(h,third,high).get("assessment")).get("score"));var entries=objects(get(h,board(ids[1]),"DemandPlanner").get("items"));assertEquals(third,object(entries.getFirst().get("record")).get("sys_id"));assertEquals(List.of(first,second).stream().sorted().toList(),entries.subList(1,3).stream().map(e->object(e.get("record")).get("sys_id").toString()).toList());ProblemInvestigationsAcceptance.access(h,"demand",third,"private",FieldDispatchAcceptance.uid(h,"DemandOther"));var board=get(h,board(ids[1]),"DemandPlanner");assertEquals(2,board.get("total"));assertFalse(JSON.writeValueAsString(board).contains(third));assertEquals(1,objects(board.get("items")).getFirst().get("rank"));result(h.json("PATCH",record(first),map("description","Changed business case"),auth("DemandPlanner")));board=get(h,board(ids[1]),"DemandPlanner");var stale=objects(board.get("items")).stream().filter(e->object(e.get("record")).get("sys_id").equals(first)).findFirst().orElseThrow();assertEquals(false,stale.get("current"));assertEquals(0,stale.get("rank"));assertEquals(0,get(h,board(ids[1]).replace("2027","2028"),"DemandPlanner").get("total"));var reassess=body(h,first,ids[1]);reassess.put("year",2028);save(h,first,reassess);assertEquals(1,get(h,board(ids[1]),"DemandPlanner").get("total"));assertEquals(1,get(h,board(ids[1]).replace("2027","2028"),"DemandPlanner").get("total"));
 }
 static void authority(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];var command=body(h,id,ids[1]);Map<String,Object> original,portfolio;try(var db=h.store.open()){original=Service.schema(db,"demand");portfolio=Service.schema(db,"portfolio");}
  for(String field:List.of("description","state","score")){var schema=new LinkedHashMap<>(original);schema.put("field_rules",map(field,map("type","string","read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"demand",schema);try{assertEquals(403,h.get(api(id),auth("DemandPlanner")).statusCode());assertEquals(403,h.get(board(ids[1]),auth("DemandPlanner")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"demand",original);}}
  for(String field:List.of("update","description","state","score")){var schema=new LinkedHashMap<>(original);if(field.equals("update")){var roles=new LinkedHashMap<>(object(original.get("record_roles")));roles.put("update",List.of("admin"));schema.put("record_roles",roles);}else schema.put("field_rules",map(field,map("type","string","write_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"demand",schema);try{assertEquals(false,get(h,api(id),"DemandPlanner").get("can_edit"));assertEquals(403,h.json("POST",api(id),command,auth("DemandPlanner")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"demand",original);}}
  for(String restriction:List.of("create","read")){var schema=new LinkedHashMap<>(original);var roles=new LinkedHashMap<>(object(original.get("record_roles")));roles.put(restriction,List.of("admin"));schema.put("record_roles",roles);ReferencePickerAcceptance.writeSchema(h,"demand",schema);try{var page=h.get("/portfolios",auth("DemandPlanner"));assertEquals(200,page.statusCode());assertFalse(html(page).contains("href=\"/record/demand/new\""));if(restriction.equals("read"))assertEquals(403,h.get(board(ids[1]),auth("DemandPlanner")).statusCode());else assertEquals(false,get(h,board(ids[1]),"DemandPlanner").get("can_create_demand"));}finally{ReferencePickerAcceptance.writeSchema(h,"demand",original);}}
  var noCreation=new LinkedHashMap<>(portfolio);var creationRoles=new LinkedHashMap<>(object(portfolio.get("record_roles")));creationRoles.put("create",List.of("admin"));noCreation.put("record_roles",creationRoles);ReferencePickerAcceptance.writeSchema(h,"portfolio",noCreation);try{assertFalse(html(h.get("/portfolios",auth("DemandPlanner"))).contains("href=\"/record/portfolio/new\""));}finally{ReferencePickerAcceptance.writeSchema(h,"portfolio",portfolio);}
  var allowed=new LinkedHashMap<>(original);allowed.put("field_rules",map("score",map("type","integer","write_roles",List.of("admin","agent"))));ReferencePickerAcceptance.writeSchema(h,"demand",allowed);assertEquals(true,get(h,api(id),"DemandPlanner").get("can_edit"));ReferencePickerAcceptance.writeSchema(h,"demand",original);save(h,id,body(h,id,ids[1]));ProblemInvestigationsAcceptance.access(h,"portfolio",ids[1],"private",FieldDispatchAcceptance.uid(h,"DemandOther"));var hidden=get(h,api(id),"DemandPlanner");assertEquals("",object(hidden.get("assessment")).get("portfolio_id"));assertFalse(JSON.writeValueAsString(hidden).contains(ids[1]));state(h,id,"screen",200);state(h,id,"qualified",404);assertEquals(404,h.get(board(ids[1]),auth("DemandPlanner")).statusCode());ProblemInvestigationsAcceptance.access(h,"portfolio",ids[1],"workspace","");result(h.json("PATCH","/api/now/table/portfolio/"+ids[1],map("state","retired"),auth("DemandPlanner")));state(h,id,"qualified",409);result(h.json("PATCH","/api/now/table/portfolio/"+ids[1],map("state","active"),auth("DemandPlanner")));
  var noPortfolio=new LinkedHashMap<>(portfolio);var proles=new LinkedHashMap<>(object(portfolio.get("record_roles")));proles.put("read",List.of("admin"));noPortfolio.put("record_roles",proles);ReferencePickerAcceptance.writeSchema(h,"portfolio",noPortfolio);assertTrue(objects(get(h,api(id),"DemandPlanner").get("portfolios")).isEmpty());ReferencePickerAcceptance.writeSchema(h,"portfolio",portfolio);
  var nativeOnly=new LinkedHashMap<>(original);nativeOnly.put("version",Approvals.version(original)+1);nativeOnly.put("transition_rules",map());ReferencePickerAcceptance.writeSchema(h,"demand",nativeOnly);try{assertEquals(false,get(h,api(id),"DemandPlanner").get("current"));state(h,id,"qualified",409);save(h,id,body(h,id,ids[1]));state(h,id,"qualified",200);var locked=new LinkedHashMap<>(nativeOnly);locked.put("field_rules",map("state",map("type","string","write_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"demand",locked);assertEquals(false,get(h,api(id),"DemandPlanner").get("can_decide"));assertEquals(403,h.json("POST",api(id),decision(h,id,"approved"),auth("DemandPlanner")).statusCode());ReferencePickerAcceptance.writeSchema(h,"demand",nativeOnly);assertEquals(409,h.json("POST",api(id),decision(h,id,"approved"),auth("DemandPlanner")).statusCode());approve(h,id);try(var db=h.store.open()){db.update("UPDATE os_user SET active=0 WHERE name='DemandReviewer'");db.connection.commit();}assertEquals(409,h.json("POST",api(id),decision(h,id,"approved"),auth("DemandPlanner")).statusCode());try(var db=h.store.open()){db.update("UPDATE os_user SET active=1 WHERE name='DemandReviewer'");db.connection.commit();}save(h,id,decision(h,id,"approved"));state(h,id,"screen",200);var bypass=new LinkedHashMap<>(nativeOnly);var flow=new LinkedHashMap<>(object(nativeOnly.get("flow")));flow.put("screen",List.of("qualified","approved"));bypass.put("flow",flow);ReferencePickerAcceptance.writeSchema(h,"demand",bypass);state(h,id,"approved",409);}finally{ReferencePickerAcceptance.writeSchema(h,"demand",original);}
 }
 static void concurrency(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];var command=body(h,id,ids[1]);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{start.await();return h.json("POST",api(id),command,auth("DemandPlanner")).statusCode();});var b=pool.submit(()->{start.await();return h.json("POST",api(id),command,auth("DemandPlanner")).statusCode();});start.countDown();assertEquals(Set.of(200,409),Set.of(a.get(),b.get()));}try(var db=h.store.open()){var row=db.one("SELECT * FROM os_demand_assessment WHERE record_id=?",id);for(int n=2;n<100;n++)db.update("INSERT INTO os_demand_assessment(record_id,revision,portfolio_id,planning_year,score,detail) VALUES(?,?,?,?,?,?)",id,n,ids[1],2027,84,JSON.writeValueAsString(row.get("detail")));PlatformFoundationTest.bind(db);for(int n=1;n<100;n++){String other=Service.create(db,"demand",map("short_description","Capacity demand"),"admin").get("sys_id").toString();db.update("INSERT INTO os_demand_assessment(record_id,revision,portfolio_id,planning_year,score,detail) VALUES(?,1,?,?,?,?)",other,ids[1],2027,84,JSON.writeValueAsString(row.get("detail")));}db.connection.commit();}save(h,id,body(h,id,ids[1]));assertEquals(100,objects(get(h,api(id),"DemandPlanner").get("history")).size());assertEquals(400,h.json("POST",api(id),body(h,id,ids[1]),auth("DemandPlanner")).statusCode());String extra=create(h,"Beyond capacity");assertEquals(400,h.json("POST",api(extra),body(h,extra,ids[1]),auth("DemandPlanner")).statusCode());var otherYear=body(h,extra,ids[1]);otherYear.put("year",2028);save(h,extra,otherYear);
 }
}
